mapper.select:
select id, title, kind, status, updated_at
from (
    select id, title, 'COURSE' kind, status, updated_at from courses
    union all
    select id, name title, 'EXERCISE' kind, status, updated_at from exercises
) content
order by updated_at desc
limit #{limit}

select u.id, u.nickname, u.phone, u.avatar_url, u.status, u.created_at, u.updated_at, count(w.id) workout_count, coalesce(sum(w.duration_minutes), 0) total_minutes from users u left join workout_records w on w.user_id = u.id
lower(coalesce(u.nickname, '')) like concat('%', lower(#{query}), '%') or coalesce(u.phone, '') like concat('%', #{query}, '%')
group by u.id, u.nickname, u.phone, u.avatar_url, u.status, u.created_at, u.updated_at order by u.created_at desc limit #{limit} offset #{offset}

select count(*) from courses

    lower(title) like concat('%', lower(#{query}), '%')
    and status = #{status}

select * from courses

    lower(title) like concat('%', lower(#{query}), '%')
    and status = #{status}

order by sort_order, updated_at desc
limit #{limit} offset #{offset}

select count(*) from exercises

    lower(name) like concat('%', lower(#{query}), '%')
    and status = #{status}

select * from exercises

    lower(name) like concat('%', lower(#{query}), '%')
    and status = #{status}

order by sort_order, updated_at desc
limit #{limit} offset #{offset}

mapper.update:
update training_plans
set title = trim(#{request.title}), week_number = #{request.weekNumber},
    sessions_per_week = #{request.sessionsPerWeek},
    description = nullif(trim(#{request.description}), ''), active = #{request.active},
    sort_order = #{request.sortOrder}
where id = #{id}

mapper.select:
select c.*, count(cc.id) checkin_count from campaigns c left join campaign_checkins cc on cc.campaign_code = c.code
lower(c.title) like concat('%', lower(#{query}), '%') or lower(c.code) like concat('%', lower(#{query}), '%')
group by c.id, c.code, c.title, c.rules_text, c.start_date, c.end_date, c.status, c.sort_order, c.created_at, c.updated_at order by c.sort_order, c.updated_at desc limit #{limit} offset #{offset}

mapper.update:
update campaigns
set code = upper(replace(replace(trim(#{request.code}), '-', '_'), ' ', '_')),
    title = trim(#{request.title}), rules_text = trim(#{request.rulesText}),
    start_date = #{request.startDate}, end_date = #{request.endDate}, status = #{request.status},
    sort_order = #{request.sortOrder}
where id = #{id}

mapper.select:
select w.id, w.user_id, coalesce(u.nickname, concat('用户 ', u.id)) user_name, w.course_id, c.title course_title, w.duration_minutes, w.completion_percent, w.started_at, w.completed_at from workout_records w join users u on u.id = w.user_id join courses c on c.id = w.course_id
lower(coalesce(u.nickname, '')) like concat('%', lower(#{query}), '%') or lower(c.title) like concat('%', lower(#{query}), '%')
order by w.completed_at desc limit #{limit} offset #{offset}

mapper.update:
update device_categories
set name = trim(#{request.name}), device_model = trim(#{request.deviceModel}),
    sn_prefix = upper(trim(#{request.snPrefix})), sort_order = #{request.sortOrder}
where id = #{id}

mapper.select:
select count(*) from devices d
lower(d.name) like concat('%', lower(#{query}), '%') or lower(d.code) like concat('%', lower(#{query}), '%') or lower(d.serial_number) like concat('%', lower(#{query}), '%')
and d.category = #{category}

select d.*, count(uds.user_id) bound_user_count from devices d left join user_device_selections uds on uds.device_id = d.id
lower(d.name) like concat('%', lower(#{query}), '%') or lower(d.code) like concat('%', lower(#{query}), '%') or lower(d.serial_number) like concat('%', lower(#{query}), '%')
and d.category = #{category}
group by d.id, d.code, d.name, d.category, d.serial_number, d.device_model, d.bed_type, d.spring_config, d.purchased_on, d.connected, d.active, d.sort_order, d.created_at, d.updated_at order by d.sort_order, d.updated_at desc limit #{limit} offset #{offset}

mapper.update:
update devices
set code = upper(replace(replace(trim(#{request.code}), '-', '_'), ' ', '_')),
    name = trim(#{request.name}), bed_type = trim(#{request.bedType}),
    spring_config = trim(#{request.springConfig}), purchased_on = #{request.purchasedOn},
    connected = #{request.connected}, active = #{request.active}, sort_order = #{request.sortOrder}
where id = #{id}
